"""从课程原稿和参考源码生成可离线阅读的教学网页，不运行应用。"""
import ast
import base64
import hashlib
import html
import json
import re
import sys
from pathlib import Path
import markdown
ROOT=Path(__file__).resolve().parents[1]
sys.path.insert(0,str(ROOT/'lessons'))
from content import LESSONS
def esc(x):return html.escape(str(x),quote=True)
EXPLANATIONS={
'Runner':{'__init__':'保存服务端唯一活动任务、条件锁与缓存模型；不要把这些对象放到浏览器。','source':'把source_id解析为有限清单或持续inbox，不接受HTTP任意路径。','start':'在锁内拒绝并发任务，保存初始 Run 后启动一个后台线程。','control':'把用户动作变成状态变更并唤醒等待线程；不是直接抢占模型。','snapshot':'读取内存中一致的Run与最新帧；初始化恢复才查数据库，不触发模型。','_boundary':'只在帧边界暂停或停止；wait 会释放条件锁。','_work':'加载一次模型并串行遍历；先提交 Frame/Run，再发布内存更新。','_frame':'检查源文件、解码、保存原始字节与哈希，再调用适配器。','close':'请求停止并有界等待；决定是否可以关闭共享数据库连接。'},
'Store':{'__init__':'检查教学库名、单实例锁、建表与中断恢复；连接是持久连接。','save_run':'按 id 插入或更新运行记录；状态与 JSON 保持一致。','save_frame':'用一个事务保存当前帧及运行汇总；提交失败抛出。','runs':'任务列表分页；created_at 排序。','frames':'单任务的帧列表分页；按 frame_id 排序。','frame':'用 run_id/frame_id 联合定位，包括内部 image_path。','get_run':'根据任务 ID 查询持久化快照。','latest_run':'重启后恢复最近一次可读任务。','ping':'SELECT 1 只说明数据库可达，不说明模型可用。','close':'关闭连接，由应用生命周期负责调用。'},
'PytorchOBBAdapter':{'load':'验证可信权重，加载 CPU FP32 模型，预热并检查 CSL 输出，记录类别和哈希。','predict':'验证 BGR 输入和参数，依次预处理、前向、旋转后处理，输出公共四点框。'},
}
def walkthrough(path):
    if path.suffix!='.py':return ''
    tree=ast.parse(path.read_text(encoding='utf-8-sig'));rows=[]
    for cls in tree.body:
        if isinstance(cls,ast.ClassDef) and cls.name in EXPLANATIONS:
            for f in cls.body:
                if isinstance(f,(ast.FunctionDef,ast.AsyncFunctionDef)) and f.name in EXPLANATIONS[cls.name]:
                    rows.append(f'<tr><td><code>{cls.name}.{f.name}</code></td><td>{f.lineno}–{f.end_lineno}</td><td>{EXPLANATIONS[cls.name][f.name]}</td></tr>')
    return '<div class="walk"><h4>按函数理解这个文件</h4><table><tr><th>函数</th><th>参考文件行号</th><th>阅读重点</th></tr>'+''.join(rows)+'</table></div>' if rows else ''

sections=[];nav=[];index=[];sources=[]
for lesson in LESSONS:
    n=lesson['id'];ident=f'lesson-{n:02d}'
    body=markdown.markdown(lesson['body'],extensions=['tables','fenced_code'])
    body=body.replace('href="../examples/','href="examples/')
    # Course screenshots stay inside the standalone HTML, just like the SVG diagrams.
    for image_path in re.findall(r'src="(../evidence/[^"]+\.png)"',body):
        image=(ROOT/'lessons'/image_path).resolve()
        if not image.is_relative_to((ROOT/'evidence').resolve()):raise ValueError('image outside evidence')
        body=body.replace(f'src="{image_path}"',f'src="data:image/png;base64,{base64.b64encode(image.read_bytes()).decode()}"')
    for slug in re.findall(r'\{\{diagram:([^}]+)\}\}',body):
        raw=(ROOT/'diagrams'/f'{slug}.html').read_text(encoding='utf-8')
        svg=re.search(r'<svg\b.*?</svg>',raw,re.S).group(0)
        body=body.replace('{{diagram:'+slug+'}}','<div class="diagram-container" tabindex="0" aria-label="数据流图，可横向滚动">'+svg+'</div>')
    code=[]
    for i,rel in enumerate(lesson['files']):
        p=ROOT/rel;source=p.read_text(encoding='utf-8-sig');cid=f'{ident}-code-{i}'
        destination=rel.removeprefix('reference/') if rel.startswith('reference/') else rel
        where='practice/factory_demo/'+destination if rel.startswith('reference/') else destination
        code.append(f'<details class="source"><summary>完整参考文件 · {esc(destination)} <small>{len(source.splitlines())} 行</small></summary><p class="note">手写位置：<code>{esc(where)}</code>。先按本节顺序理解各部分，再对照完整文件。</p>{walkthrough(p)}<a href="{esc(rel)}" download>下载原始文件</a><button class="copy" data-target="{cid}">复制完整代码</button><pre><code id="{cid}">{esc(source)}</code></pre></details>')
        sources.append({'lesson':n,'file':rel,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()})
    q=lesson['quiz'];opts=''.join(f'<button class="choice" data-lesson="{n}" data-choice="{i}">{chr(65+i)}. {esc(v)}</button>' for i,v in enumerate(q['options']))
    quiz=f'<div class="quiz"><h3>停下来检查理解</h3><p>{esc(q["question"])}</p><div class="choices">{opts}</div><p class="feedback" id="feedback-{n}" role="status" aria-live="polite"></p></div>'
    completion=f'<label class="complete"><input type="checkbox" data-complete="{n}"> 我已完成本节动手与验收，并能解释关键原因</label>'
    sections.append(f'<section class="lesson" id="{ident}" data-lesson="{n}"><div class="eyebrow">LESSON {n:02d} / 19</div><h1>{esc(lesson["title"])}</h1><p class="goal"><strong>本节目标：</strong>{esc(lesson["goal"])}</p>{body}{"".join(code)}{quiz}{completion}<div class="lesson-actions">'+(f'<a href="#lesson-{n-1:02d}">← 上一节</a>' if n else '<span>从这里开始</span>')+(f'<a href="#lesson-{n+1:02d}">下一节 →</a>' if n<19 else '<a href="#lesson-00">返回第一节</a>')+'</div></section>')
    nav.append(f'<a href="#{ident}" data-nav="{n}"><span class="number">{n:02d}</span><span>{esc(lesson["title"])}</span><span class="done-dot" aria-hidden="true"></span></a>')
    plain=html.unescape(re.sub('<[^>]+>',' ',body));index.append({'id':ident,'title':lesson['title'],'text':re.sub(r'\s+',' ',plain)})
    (ROOT/'lessons'/f'{n:02d}.md').write_text(f'# {n:02d} {lesson["title"]}\n\n目标：{lesson["goal"]}\n'+lesson['body']+'\n\n参考文件：\n'+''.join('- `'+p+'`\n' for p in lesson['files']),encoding='utf-8')

css='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f2f4f3;color:#203039;font:17px/1.9 'Segoe UI','Microsoft YaHei',sans-serif}button,input{font:inherit}button,a,summary,input{outline-offset:4px}a{color:#126a59;text-underline-offset:3px}button{cursor:pointer;border:1px solid #b4c7bd;border-radius:5px;background:#fff;padding:8px 12px;color:#203039}button:hover{background:#edf5f1}a:focus-visible,button:focus-visible,summary:focus-visible,input:focus-visible{outline:3px solid #177b68}.sidebar{position:fixed;inset:0 auto 0 0;width:310px;background:#152d32;color:#e9f4ee;padding:24px 18px;overflow-y:auto}.brand{font-size:22px;font-weight:750}.tag{font-size:13px;color:#bcd3c9;margin:6px 0 18px}.sidebar input[type=search]{width:100%;padding:8px 10px;border:1px solid #92ada0;border-radius:5px;background:#fff;font-size:14px}.sidebar label{font-size:13px}.progress{margin:18px 0 12px;font-size:13px}.progress progress{width:100%;accent-color:#75c4a3;height:9px}.sidebar nav a{display:grid;grid-template-columns:28px 1fr 10px;gap:5px;align-items:center;color:#dbece4;text-decoration:none;font-size:13px;line-height:1.6;padding:9px 7px;border-left:3px solid transparent}.sidebar nav a.active{background:#294a4b;border-left-color:#75c4a3;color:white}.number{font:12px Consolas,monospace;color:#abcabc}.done-dot{width:7px;height:7px;border:1px solid #a6bfb2;border-radius:50%}.done .done-dot{background:#86d2ad}.side-actions{display:flex;flex-wrap:wrap;gap:7px;margin:14px 0}.side-actions button{font-size:12px;padding:5px 8px}.sidebar .hint{font-size:12px;line-height:1.6;color:#c1d5cb}main{margin-left:310px;padding:26px 36px 70px;min-width:0;max-width:1830px}.intro{margin-bottom:25px;padding:16px 0 24px;border-bottom:2px solid #177b68}.intro h1{font-size:30px;line-height:1.5;margin:4px 0 12px}.intro p{color:#52676b;font-size:15px;margin:8px 0}.tags span{display:inline-block;padding:2px 8px;margin:4px 6px 0 0;border:1px solid #bacdc2;border-radius:4px;font-size:12px;background:#edf5f1}.lesson{background:#fff;border:1px solid #d3dfd7;padding:32px 40px;margin-bottom:25px;min-width:0;overflow-wrap:anywhere}.lesson[hidden]{display:none}.lesson img{display:block;max-width:100%;height:auto;border:1px solid #cbd7cf}.lesson h1{font-size:30px;margin:7px 0 20px;line-height:1.5}.eyebrow{font:12px Consolas,monospace;letter-spacing:.13em;color:#52676b}.goal{padding:13px 17px;background:#edf5f1;border-left:4px solid #177b68}.lesson h2{font-size:22px;margin:30px 0 15px;border-top:1px solid #dfe5e1;padding-top:20px}.lesson h3{font-size:19px;margin:20px 0 10px}.lesson h4{font-size:16px;margin:16px 0}li{margin:8px 0}code{font-family:Consolas,'Microsoft YaHei',monospace;font-size:.88em;background:#edf5f1;padding:2px 5px;overflow-wrap:anywhere}pre{padding:18px;overflow:auto;border:1px solid #d8e6dc;background:#f0f6f2;font-size:14px;line-height:1.7;max-height:620px}pre code{padding:0;background:none;white-space:pre}.source{border:1px solid #c8d9ce;margin:18px 0;background:#fcfefd;padding:14px 16px;min-width:0}.source summary{cursor:pointer;font-weight:600;color:#126a59}.source summary small{font-weight:400;color:#52676b;margin-left:8px}.copy{font-size:13px;margin-left:12px}.note{font-size:13px;color:#52676b}.walk{font-size:14px}table{display:block;overflow-x:auto;border-collapse:collapse;max-width:100%;font-size:14px}td,th{border:1px solid #d2dfd6;padding:8px 10px;vertical-align:top;text-align:left;min-width:90px}th{background:#edf5f1}.quiz{margin:30px 0 22px;border-top:2px solid #177b68;padding-top:15px}.choices{display:grid;gap:10px;max-width:850px}.choice{text-align:left}.choice.correct{border-color:#177b68;background:#e3f2e9}.choice.wrong{border-color:#a44d28;background:#fff1e9}.feedback{min-height:30px;color:#126a59;font-size:15px}.complete{display:block;padding:15px;border:1px solid #bbd3c3;background:#edf5f1;font-size:15px}.complete input{width:18px;height:18px;vertical-align:middle;margin-right:8px;accent-color:#177b68}.lesson-actions{display:flex;justify-content:space-between;gap:20px;margin-top:25px;font-size:15px}.diagram-container{width:100%;overflow-x:auto;border:1px solid #cad7cf;margin:22px 0}.diagram-container svg{display:block;width:100%;min-width:1280px}.search-results{padding:20px;background:white;border:1px solid #cbdacf;margin-bottom:24px}.search-results[hidden]{display:none}.search-result{display:block;padding:10px 0;border-bottom:1px solid #e0e8e2;text-decoration:none}.search-result small{display:block;color:#52676b;font-size:13px}.status{font-size:12px;color:#dcece4;min-height:18px}footer{font-size:13px;color:#52676b}noscript{display:block;padding:15px;border:1px solid #bbd3c3}.source a{font-size:13px}
@media(max-width:1050px){.sidebar{position:static;width:100%;padding:20px}.sidebar nav{max-height:240px;overflow:auto}.side-actions{margin:10px 0}main{margin:0;padding:20px}.lesson{padding:25px}.sidebar .progress{max-width:550px}}
@media(max-width:560px){main{padding:12px}.lesson{padding:20px 14px}.lesson h1{font-size:25px}.intro h1{font-size:25px}body{font-size:16px}.source{padding:10px}.source summary{font-size:14px}.copy{margin:8px 0}.lesson-actions{font-size:14px}}
@media print{.sidebar,.intro,.search-results,.copy,.choice,.complete,.lesson-actions{display:none}main{margin:0;padding:0}.lesson,.lesson[hidden]{display:block;border:0;padding:0;break-before:page}.diagram-container{overflow:visible;break-inside:avoid}.diagram-container svg{min-width:0}pre{max-height:none;white-space:pre-wrap}pre code{white-space:pre-wrap}h2,h3{break-after:avoid}.source:not([open]){display:block}a{color:inherit}}'''
data={'lessons':[{'id':x['id'],'quiz':x['quiz']} for x in LESSONS],'search':index}
data_json=json.dumps(data,ensure_ascii=False).replace('<','\\u003c')
js='''const data=JSON.parse(document.querySelector('#course-data').textContent),KEY='factory-demo-tutorial-v1';let completed=new Set(),storageOK=true;try{const raw=JSON.parse(localStorage.getItem(KEY)||'[]');completed=new Set(Array.isArray(raw)?raw.filter(n=>Number.isInteger(n)&&n>=0&&n<20):[])}catch{storageOK=false}
function update(){document.querySelector('#count').textContent=completed.size+' / 20 节手动完成';document.querySelector('progress').value=completed.size;document.querySelectorAll('[data-complete]').forEach(x=>x.checked=completed.has(Number(x.dataset.complete)));document.querySelectorAll('[data-nav]').forEach(x=>x.classList.toggle('done',completed.has(Number(x.dataset.nav))));if(!storageOK)document.querySelector('#status').textContent='浏览器未允许保存进度；当前会话仍可使用。'}
function save(){try{localStorage.setItem(KEY,JSON.stringify([...completed]))}catch{storageOK=false}update()}
function show(){const match=location.hash.match(/^#lesson-(\\d{2})$/);const n=match&&Number(match[1])<20?Number(match[1]):0;document.querySelectorAll('.lesson').forEach(s=>s.hidden=Number(s.dataset.lesson)!==n);document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',Number(a.dataset.nav)===n));document.title='第 '+String(n).padStart(2,'0')+' 课 · Factory Demo 从零实现';if(location.hash)document.getElementById('lesson-'+String(n).padStart(2,'0')).scrollIntoView({behavior:'instant',block:'start'})}
document.querySelectorAll('[data-complete]').forEach(x=>x.addEventListener('change',()=>{const n=Number(x.dataset.complete);x.checked?completed.add(n):completed.delete(n);save()}));
document.querySelectorAll('.choice').forEach(b=>b.addEventListener('click',()=>{const n=Number(b.dataset.lesson),q=data.lessons[n].quiz,ok=Number(b.dataset.choice)===q.answer;document.querySelectorAll('.choice[data-lesson="'+n+'"]').forEach(x=>x.classList.remove('correct','wrong'));b.classList.add(ok?'correct':'wrong');document.querySelector('#feedback-'+n).textContent=(ok?'正确。':'再想一想。')+q.explain}));
document.querySelectorAll('.copy').forEach(b=>b.addEventListener('click',async()=>{const value=document.getElementById(b.dataset.target).textContent;try{await navigator.clipboard.writeText(value);b.textContent='已复制'}catch{const t=document.createElement('textarea');t.value=value;document.body.append(t);t.select();b.textContent=document.execCommand('copy')?'已复制':'请手动选中复制';t.remove()}setTimeout(()=>b.textContent='复制完整代码',1800)}));
const query=document.querySelector('#query'),results=document.querySelector('#search-results');function search(){const q=query.value.trim().toLowerCase();results.replaceChildren();results.hidden=!q;if(!q)return;const matches=data.search.filter(x=>q.split(/\\s+/).every(w=>(x.title+' '+x.text).toLowerCase().includes(w)));const h=document.createElement('h2');h.textContent='匹配 '+matches.length+' 节';results.append(h);for(const r of matches){const a=document.createElement('a');a.className='search-result';a.href='#'+r.id;a.textContent=r.title;const small=document.createElement('small');const at=Math.max(0,r.text.toLowerCase().indexOf(q)-30);small.textContent=r.text.slice(at,at+130);a.append(small);a.addEventListener('click',()=>{query.value='';search()});results.append(a)}if(!matches.length){const p=document.createElement('p');p.textContent='没有匹配课程，请尝试“坐标”“事务”“NMS”。';results.append(p)}}query.addEventListener('input',search);query.addEventListener('keydown',e=>{if(e.key==='Enter')results.scrollIntoView();if(e.key==='Escape'){query.value='';search();query.blur()}});document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();query.focus()}});
document.querySelector('#export').addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([JSON.stringify({course:'factory-demo-tutorial-v1',completed:[...completed]},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='factory-demo-learning-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});
document.querySelector('#print').addEventListener('click',()=>window.print());window.addEventListener('hashchange',show);update();show();'''
page=f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Factory Demo · 从零实现教学课程</title><style>{css}</style></head><body><aside class="sidebar"><div class="brand">从零实现 Factory Demo</div><p class="tag">一步一步完成一个真实检测应用</p><label for="query">查找课程 · Ctrl+K</label><input id="query" type="search" placeholder="例如：事务、四点框、暂停"><div class="progress"><span id="count">0 / 20 节手动完成</span><progress max="20" value="0" aria-label="学习进度"></progress></div><nav aria-label="课程目录">{''.join(nav)}</nav><div class="side-actions"><button id="export">导出学习进度</button><button id="print">打印课程</button></div><p class="hint">进度只保存在当前浏览器。复选框不代表自动验收通过。</p><div id="status" class="status" role="status"></div></aside><main><header class="intro"><h1>从最小示例到完整应用</h1><p>20 节课程：概念 → 最小例子 → 完整实现 → 联调 → 验收。默认会基础 Python，不要求你已经熟悉 Vue、FastAPI 或 PostgreSQL。</p><div class="tags"><span>离线网页</span><span>独立练习区</span><span>完整参考源码</span><span>示例与真实推理分开</span></div><p>工作目录：<code>{esc(str(ROOT))}</code> · <a href="README.md">课程使用说明</a> · <a href="evidence/validation.json">验证记录</a></p></header><noscript>脚本未启用：下方仍显示全部课程及完整代码；搜索、进度和自测反馈不可用。</noscript><div class="search-results" id="search-results" hidden></div>{''.join(sections)}<footer>2026-10-28 · 课程对应 factory_demo V1.3 工业展示版。参考实现对应 V1.3 源码快照，并保留独立教学端口、数据库与路径；课程操作不会修改正式项目。图示随 V1.3 数据流说明同步更新；历史来源与当前同步哈希见 evidence/source-provenance.json 和 evidence/revision-v1.2.json。</footer></main><script id="course-data" type="application/json">{data_json}</script><script>{js}</script></body></html>'''
(ROOT/'index.html').write_text(page,encoding='utf-8')
(ROOT/'evidence/content-manifest.json').write_text(json.dumps({'lessons':20,'source_blocks':len(sources),'files':sources,'diagrams':5},ensure_ascii=False,indent=2),encoding='utf-8')
print(json.dumps({'html_bytes':len(page.encode()),'lessons':20,'full_source_blocks':len(sources)},ensure_ascii=False))
if __name__=='__main__':pass

